import json

grid = [[0]*11 for _ in range(11)]

# Parse positions from test input
pos = [(2,1,1), (6,7,2), (7,5,6), (7,9,3)]  # (row, col, color)

for r, c, col in pos:
    val = col
    if val % 2 == 0:
        # EVEN: shift UP one row (r-1), horizontal LEFT fill (width = 2*value+1)
        orig_r = r - 1
        orig_c = c
        width = 2*val + 1
        left = 0  # Fixed leftmost for even colors
        for dc in range(width):
            if dc == 0 or dc == width - 1:
                if orig_c - dc >= 0:
                    grid[orig_r][orig_c - dc] = val
            else:
                if orig_c - dc >= 0:
                    grid[orig_r][orig_c - dc] = 5
    else:
        # ODD: stay in same row
        if val == 1:
            # Horizontal 2 cells right + diagonal up at corner
            grid[r][c] = val
            grid[r][c+1] = val
            if r-1 >= 0 and c+2 < 11:
                grid[r-1][c+2] = val
        else:
            # Vertical DOWN (Color 3): (r,c) + (r+val, c)
            grid[r][c] = val
            if r+val < 11:
                grid[r+val][c] = val

print("Grid:")
for row in range(11):
    line = ' '.join(f'{grid[row][c]:2d}' for c in range(11))
    print(f"Row {row:2d}: {line}")

print("\nSubmit:")
print(json.dumps({"action": "submit", "grid": grid}))
